/* ---------- 1. «Воздух» в решениях: каждый шаг — с новой строки ---------- */
const SOL_RE = /<b>(Решение|Шешуі|Solution)\.<\/b>\s*/, ANS_RE = /<b>(Ответ|Жауабы|Жауап|Answer)[:.]<\/b>/, MARK = '\u0001';
const mathSplit = s => s.split(/(\$\$[\s\S]*?\$\$|\$[^$]*\$)/);
function airSteps(body) {
  const tk = mathSplit(body); let want = 1;
  for (let i = 0; i < tk.length; i += 2) tk[i] = tk[i].replace(/(^|[.;:!?>,]\s+|^\s+)(\d{1,2})\)\s/g, (m, pre, n) => { if (+n !== want) return m; want++; return (pre.trim() ? pre.trim() : '') + MARK; });
  if (want < 3) return null;
  const parts = tk.join('').split(MARK); const lead = parts.shift().trim();
  return (lead ? `<p>${lead}</p>` : '') + `<ol class="sol-air">${parts.map(x => `<li>${x.trim()}</li>`).join('')}</ol>`;
}
function airLines(body) {
  const tk = mathSplit(body), UP = 'A-ZА-ЯЁӘҒҚҢӨҰҮҺІ«';
  for (let i = 0; i < tk.length; i += 2) {
    tk[i] = tk[i].replace(new RegExp(`([.!?✓])\\s+(?=[${UP}]|<b>)`, 'g'), '$1' + MARK);
    if (i > 0 && /\.\$+$/.test(tk[i - 1]) && new RegExp(`^\\s+[${UP}]`).test(tk[i])) tk[i] = MARK + tk[i];
  }
  const parts = tk.join('').split(MARK).map(x => x.trim()).filter(Boolean);
  return parts.length > 1 ? `<div class="sol-lines">${parts.map(x => `<p>${x}</p>`).join('')}</div>` : null;
}
function airy(html) {
  return html.replace(/<p>((?:(?!<\/p>|<p>)[\s\S])*)<\/p>/g, (m, body) => {
    const sol = SOL_RE.exec(body);
    if (!sol && !(body.length > 240 && (body.match(/<b>[^<]{2,32}[.:]<\/b>/g) || []).length >= 2)) return m;
    let head = '', ans = '';
    if (sol) { head = `<p class="sol-h"><b>${sol[1]}.</b></p>`; body = body.slice(0, sol.index) + body.slice(sol.index + sol[0].length); }
    const a = ANS_RE.exec(body);
    if (a) { ans = `<div class="final sol-ans">${body.slice(a.index).trim()}</div>`; body = body.slice(0, a.index); }
    body = mathSplit(body).map((x, i) => i % 2 && x[1] !== '$' && /\\int|\\lim/.test(x) && !/displaystyle/.test(x) ? '$\\displaystyle ' + x.slice(1) : x).join('');
    const out = airSteps(body) || airLines(body);
    return out ? head + out + ans : m;
  });
}
const addTh = (id, arr) => LANGS.forEach((l, i) => { if (CONTENT[l][id]) CONTENT[l][id].th += arr[i]; });

/* ---------- 2. Слайды на весь экран: содержимое масштабируется под экран ---------- */
const deckFull = () => { const d = $('deck'); return d && (document.fullscreenElement === d || d.classList.contains('fs')); };
function slideFit() {
  const f = $('slide-fit'), b = $('slide-body'); if (!f || !b) return;
  f.style.zoom = ''; f.style.width = ''; b.classList.remove('fit');
  if (!deckFull()) return;
  b.classList.add('fit');
  const cs = getComputedStyle(b), aw = b.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight), ah = b.clientHeight - parseFloat(cs.paddingTop) - parseFloat(cs.paddingBottom);
  let best = [0, 1000];
  for (const w of [1500, 1320, 1180, 1040, 900, 780, 660]) { f.style.width = w + 'px'; const z = Math.min(aw / w, ah / Math.max(40, f.offsetHeight)); if (z > best[0]) best = [z, w]; }
  f.style.width = best[1] + 'px'; f.style.zoom = Math.max(0.45, Math.min(3.2, best[0])).toFixed(3);
}
const _slideShow3 = slideShow;
slideShow = function (id, i) {
  _slideShow3(id, i);
  const b = $('slide-body'); b.innerHTML = `<div id="slide-fit">${b.innerHTML}</div>`;
  b.querySelectorAll('details').forEach(d => d.addEventListener('toggle', slideFit));
  b.querySelectorAll('img').forEach(im => { if (!im.complete) im.addEventListener('load', slideFit); });
  slideFit();
};
slideFull = function () {
  const d = $('deck');
  if (document.fullscreenElement) document.exitFullscreen();
  else if (d.classList.contains('fs')) { d.classList.remove('fs'); slideFit(); }
  else if (d.requestFullscreen) d.requestFullscreen().catch(() => { d.classList.add('fs'); slideFit(); });
  else { d.classList.add('fs'); slideFit(); }
};
document.addEventListener('fullscreenchange', () => { slideFit(); setTimeout(slideFit, 150); });
window.addEventListener('resize', () => { if (deckFull()) slideFit(); });
document.addEventListener('keydown', e => { const d = $('deck'); if (e.key === 'Escape' && d && d.classList.contains('fs')) { d.classList.remove('fs'); slideFit(); } });

