function wsAi() {
  const topics = [...document.querySelectorAll('.ws-topic:checked')].map(x => x.value);
  if (!topics.length) { toast(t('wsNone')); return; }
  const n = Math.max(1, Math.min(30, +$('ws-n').value || 8)), V = Math.max(1, Math.min(8, +$('ws-v').value || 2)), lv = [1, 2, 3].filter(l => $('ws-l' + l).checked).map(l => t('lvl' + l)).join(', ') || t('lvl1');
  const names = topics.map(id => '«' + C(id).t + '»').join(', '), applied = $('ws-applied').checked, sol = $('ws-sol').checked;
  const lang = ['на русском языке', 'на казахском языке', 'на английском языке'][LI()];
  const text = `Ты помощник учителя математики. Составь рабочий лист для 10–11 класса ${lang}. Темы: ${names}. Вариантов: ${V}, задач в каждом варианте: ${n}. Уровни сложности: ${lv}.${applied ? ' Все задачи — прикладные, с практическим сюжетом (физика, экономика, биология, быт).' : ''} Задачи в вариантах должны быть однотипными, но с разными числами; ответы — «красивые». Формулы пиши в LaTeX в знаках $...$. Сначала выведи варианты с нумерацией задач, затем отдельным блоком «Ключ ответов» для каждого варианта${sol ? ' и краткое решение каждой задачи по шагам, каждый шаг с новой строки' : ''}.`;
  go('ai'); setTimeout(() => aiSend(text, `${t('wsT')}: ${names} · ${V} × ${n}`), 500);
}
